using System;
using System.Collections.Generic;
using UnityEngine;
public partial class DungeonPrototype {
 public bool SaveDungeonGame(){if(battle||moving||lost)return false;try{var data=CaptureDungeonSave();var previous=DungeonSaveStore.Read();DungeonSaveStore.Write(data,DungeonSaveStore.ActiveSlot,previous!=null?previous.slotName:null);if(!cityActive)SystemMessages.Show(SystemMessageCode.Saved,"",0,DigitalIcon.Backup);return true;}catch(Exception e){Debug.LogWarning("No se pudo guardar: "+e.Message);return false;}}
 public DungeonSaveData CaptureDungeonSave(){if(cityDataOnly)return CaptureCityModelSave();var data=new DungeonSaveData{interactions=DungeonMapPersistence.Copy(interactionProgress),version=2,activeMapId=DungeonMapPersistence.RequireId(ActiveMap),maps=DungeonMapPersistence.Copy(floorSnapshots),legacyDoors=CaptureLegacyDoors(),city=cityProgress,cell=position,heading=heading,directorRestRemaining=directorRestSteps,entityStates=new List<DungeonEntityState>(mapEntityStates),player=CapturePlayerProgression(),refuge=refuge,introductionCompleted=introductionCompleted||(introduction!=null&&!introduction.Active),enemies=CaptureEnemyProgression(),triggeredEncounters=CaptureTriggeredEncounterIds()};for(int y=0;y<map.Length;y++)for(int x=0;x<map[y].Length;x++)if(explored[x,y])data.explored.Add(new Vector2Int(x,y));for(int y=0;y<map.Length;y++)for(int x=0;x<map[y].Length;x++)if(visited!=null&&visited[x,y])data.visited.Add(new Vector2Int(x,y));foreach(var pair in mapDoors)if(pair.Value!=null){var state=data.entityStates.Find(e=>e.id==pair.Key);if(state!=null)state.opened=pair.Value.IsOpen;else data.entityStates.Add(new DungeonEntityState{id=pair.Key,opened=pair.Value.IsOpen});}DungeonMapPersistence.StoreCurrent(data);return DungeonMapPersistence.Copy(data);}
 public bool LoadDungeonGame(){if(battle||moving)return false;try{var data=DungeonSaveStore.Read();if(data==null)return false;RestoreDungeonSave(data);return true;}catch(Exception e){Debug.LogWarning("No se pudo cargar: "+e.Message);return false;}}
 public void RestoreDungeonSave(DungeonSaveData data){CancelRefugeWelcome();selectingSpeedrun=false;speedrunExecuting=false;cityBackpackOpen=false;pendingDoorKeys.Clear();
  if(data==null||data.player==null)throw new ArgumentException("Partida inválida");
  data=DungeonMapPersistence.Copy(data);bool legacy=data.version==1;DungeonMapPersistence.Normalize(data,DungeonMapSettings.Current);
  var savedMap=DungeonMapPersistence.Resolve(data.activeMapId,ActiveMap);if(savedMap==null)throw new ArgumentException("Mapa guardado no disponible: "+data.activeMapId);
  if(!cityDataOnly&&savedMap!=ActiveMap){ReplaceFloor(savedMap,data,false);return;}
  interactionProgress=data.interactions??new DungeonInteractionProgress();NormalizeInteractionProgress();foreach(var record in data.enemies)if(record.defeated)RecordDungeonDefeat(record);floorSnapshots=DungeonMapPersistence.Copy(data.maps);if(cityDataOnly){if(data.city==null||!data.city.inCity){data.city=data.city??new DigitalKingdomProgress();DigitalKingdomTransit.Travel(data,ActiveMap,City.fallbackDungeonScene,null);}else InitializeCityModel(data,view);return;}if(data==null||data.player==null||!Open(data.cell))throw new ArgumentException("Partida inválida o plano cambiado");EndMakongPresentation();systemHackPending=false;systemHack=null;pendingMakongNarrative=null;pendingMakongNarrativeId=null;CloseCityView();CancelMapReveal();ResumeLoadedExploration();playerNavigation=null;directorNextSpawnTime=0;nextRespawnScan=0;directorRestSteps=0;directorSectors.Clear();itemReceipts.Clear();foreach(var effect in GetComponentsInChildren<SpeedrunDeleteEffect>()){effect.enabled=false;Destroy(effect);}StopAllCoroutines();ClearMovementInput();foreach(var bush in GetComponentsInChildren<RetroDungeonBush>())bush.ResetAfterRestore();enemyNavigationRunning=false;combatSummons.Clear();foreach(var corpse in fadingEnemies)if(corpse!=null)Destroy(corpse);fadingEnemies.Clear();pendingChests.Clear();disappearingBodies.Clear();foreach(var actor in refugeActors.Values){var visual=actor.GetComponent<GhostEnemyVisual>();actor.transform.localScale=visual!=null?Vector3.one*.75f:Vector3.one;if(visual!=null)visual.ResetToIdle();}worldDialogue.Cancel();transferMenu=nodeDecision=refugeExitLooking=devotoApproachLatched=false;battle=busy=moving=lost=levelComplete=false;activeEnemy=-1;encounter.Clear();foreach(var obj in enemyObjects)if(obj!=null)Destroy(obj);enemyObjects.Clear();enemies.Clear();enemyLives.Clear();alerted.Clear();respawnAt.Clear();slots.Clear();defeatedEnemies.Clear();triggeredEncounters.Clear();mapEntityStates=data.entityStates??new List<DungeonEntityState>();refuge=data.refuge??new RefugeProgress();MigrateRefugeNarrative();RestorePlayerProgression(data.player);introductionCompleted=true;introduction?.Skip();EndIntroPresentation(true);ReleaseIntroductionInput();
  // Dead slots first: their cells may have been occupied by other agents since defeat.
  foreach(bool dead in new[]{true,false})foreach(var record in data.enemies){if(record.defeated!=dead)continue;if(refugeSettings!=null&&record.placementId==refugeSettings.devotoPlacementId&&refuge.devotoDefeated)continue;var origin=RegionMap==null?RegionAt(record.cell):Array.Find(RegionMap.regions,z=>z.id==record.zoneId);if(origin==null||!Open(record.cell))continue;var actual=RegionMap==null?null:Array.Find(RegionMap.placedEnemies,e=>e.id==record.placementId);if(actual==null&&!string.IsNullOrEmpty(record.placementId))continue;var forced=actual??new PlacedEnemyDefinition{speciesId=record.speciesId,cell=record.cell,randomLevel=false,fixedLevel=record.level,countsTowardLimit=false};if(actual!=null&&actual.speciesId=="Makong"&&actual.holdPosition)record.cell=actual.cell;int before=enemyObjects.Count;AddEnemy(record.cell,visualKind:ArrayIndex(record.speciesId),origin:origin,placement:forced);if(enemyObjects.Count==before)continue;int index=enemyObjects.Count-1;slots[index].placement=actual;slots[index].counts=actual==null||actual.countsTowardLimit;slots[index].instanceId=record.instanceId;var stats=enemyObjects[index].GetComponent<EnemyCombatStats>();stats.instanceId=record.instanceId;stats.placementId=record.placementId;stats.category=record.category;enemyLives[index]=Mathf.Clamp(record.currentHP,0,stats.maximumHP);alerted[index]=record.alerted;RestoreExplorationState(index,record);if(record.defeated){Destroy(enemyObjects[index]);enemyObjects[index]=null;defeatedEnemies[index]=record;respawnAt[index]=slots[index].CanRespawn?Time.unscaledTime+record.respawnRemaining:-1;}}
  foreach(var id in data.triggeredEncounters??new string[0])triggeredEncounters.Add(id);explored=new bool[map[0].Length,map.Length];visited=new bool[map[0].Length,map.Length];foreach(var c in data.visited)if(Open(c))visited[c.x,c.y]=true;foreach(var c in data.explored)if(c.x>=0&&c.y>=0&&c.x<map[0].Length&&c.y<map.Length)explored[c.x,c.y]=true;WarpPlayer(data.cell,data.heading);if(refugeSettings!=null){UpdateRefugePresentation();EnsureDevotoEvent();TryGrantRefugeReward();}directorRestSteps=Mathf.Max(0,data.directorRestRemaining);EnsureMakongPlacementAfterLoad(data);if(legacy&&!restoringCitySnapshot)PopulateRegions(true);RefreshMapEntityStates(true);RestoreLegacyDoors(data.legacyDoors);RefreshDungeonSwitchVisuals();message="Partida cargada.";RestoreCityProgress(data.city);
 }
 List<DungeonEntityState> CaptureLegacyDoors(){var result=new List<DungeonEntityState>();foreach(var pair in LegacyDoors())if(pair.Value!=null)result.Add(new DungeonEntityState{id=pair.Key,opened=pair.Value.IsOpen});return result;}
 Dictionary<string,DungeonDoor> LegacyDoors(){return new Dictionary<string,DungeonDoor>{{"legacy.exit",exitDoor},{"refuge.exit",refugeDoor},{"corridor.door",zoneTwoDoor}};}
 void RestoreLegacyDoors(List<DungeonEntityState> states){var doors=LegacyDoors();foreach(var state in states){DungeonDoor door;if(doors.TryGetValue(state.id,out door)&&door!=null){if(state.opened)door.SetOpenImmediately();else door.SetClosedImmediately();}}}
 void RestorePlayerProgression(PlayerProgressionRecord record){StartPlayClock(record.hasPlayTime?record.playedSeconds:0);lastSavePoint=record.lastSavePoint==null?null:DungeonMapPersistence.Copy(record.lastSavePoint);ownedEquipment.Clear();equippedIds=new string[3];foreach(var item in record.inventory){if(Array.Exists(Character.equipment,e=>e!=null&&e.id==item.itemId))ownedEquipment.Add(item.itemId);}itemCounts=new int[inventorySettings.items.Length];foreach(var item in record.inventory){int i=Array.FindIndex(inventorySettings.items,e=>e!=null&&e.id==item.itemId);if(i>=0)itemCounts[i]=Mathf.Max(0,item.quantity);}if(record.equipmentIds!=null)for(int i=0;i<Mathf.Min(3,record.equipmentIds.Length);i++)equippedIds[i]=record.equipmentIds[i];coins=Mathf.Max(0,record.coins);pendingCombatDrops=record.pendingCombatDrops??new List<InventoryItemRecord>();RestorePlayerLevel(record);RestoreHackAvailability(record);EnsureEquipment();hp=Mathf.Clamp(record.currentHP,1,MaximumHP);playerBits=record.hasBits?Mathf.Clamp(record.currentBits,0,MaximumBits):MaximumBits;}
}
